.channel-list article {min-width:0;overflow-wrap:anywhere;padding:12px;border:1px solid #eee;border-radius:10px;}
.channel-thumbnail {width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:8px;display:block;margin-bottom:10px;}
.metadata-form {display:grid;gap:14px;max-width:700px;margin:20px 0;}
.metadata-form label {display:grid;gap:8px;}
.metadata-form input,.metadata-form textarea,.playlist-page select {width:100%;min-width:0;font:inherit;padding:10px;border:1px solid #aaa;border-radius:8px;}
.playlist-page fieldset {min-width:0;margin:20px 0;border:1px solid #ddd;}
.playlist-editor {padding-left:24px;}
.playlist-editor li {overflow-wrap:anywhere;margin:16px 0;}
