  assert.equal(found.status(),200);
  if(!(await found.json()).length){
   const fresh=await browser.newContext();
   const response=await fresh.request.post(base+'/api/auth/register',{headers:{Origin:base},data:{username:name,email:'review6_'+randomUUID().replaceAll('-','')+'@example.com',password:randomUUID()}});
   assert.equal(response.status(),201);await fresh.close();
  }
