  const {session}=useAuth(),write=useWrite(),{value:channel,error,reload}=useResource<Channel>('/channels/'+encodeURIComponent(username))
  const [busy,setBusy]=useState(false),[actionError,setActionError]=useState('')
  async function subscribe(){if(!channel)return;setBusy(true);setActionError('');try{await write(`/channels/${encodeURIComponent(username)}/subscription`,channel.subscribed_by_me?'DELETE':'PUT');window.dispatchEvent(new Event('subscriptions-changed'))}catch(e){setActionError((e as Error).message)}finally{setBusy(false)}}
  if(error&&!channel)return <p role="alert">{error}</p>;if(!channel)return <p>Загрузка канала…</p>
  return <section className="channel-page">{error&&<p role="alert">{error}</p>}<h1>{channel.title}</h1><p>Автор: {channel.username}</p><p className="video-description">{channel.description}</p><p>Подписчиков: <span data-testid="subscribers-count">{channel.subscribers_count}</span></p>{!channel.owned_by_me&&(session?<button disabled={busy} onClick={()=>void subscribe()}>{channel.subscribed_by_me?'Отписаться':'Подписаться'}</button>:<Link to="/login">Войдите, чтобы подписаться</Link>)}{actionError&&<p role="alert">{actionError}</p>}{channel.owned_by_me&&<details><summary>Редактировать канал</summary><MetadataForm title={channel.title} description={channel.description} label="Сохранить канал" onSave={async data=>{await write('/me/channel','PATCH',data);reload()}}/><Link to="/studio/playlists">Управлять плейлистами</Link></details>}<h2>Видео</h2><Listing<Video> path={`/channels/${encodeURIComponent(username)}/videos`} render={item=><Link to={item.watch_url||`/watch/${item.id}`}><img className="channel-thumbnail" src={item.thumbnail_url} alt=""/>{item.title}</Link>}/><h2>Плейлисты</h2><Listing<Playlist> path={`/channels/${encodeURIComponent(username)}/playlists`} render={playlistLink}/></section>
}
