const {chromium}=require('playwright-core');
const {randomUUID}=require('node:crypto');
const {writeFileSync}=require('node:fs');
const assert=require('node:assert/strict');
const base='http://localhost:8080';
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 try{
  const context=await browser.newContext({viewport:{width:390,height:1000}});
  const name='ind7_'+randomUUID().replaceAll('-','').slice(0,12);
  let response;
  for(let n=0;n<5;n++){
   response=await context.request.post(base+'/api/auth/register',{headers:{Origin:base},data:{username:name,email:name+'@example.com',password:randomUUID()}});
   if(response.status()!==429)break;await new Promise(resolve=>setTimeout(resolve,21000));
  }
  assert.equal(response.status(),201);
  const session=await response.json(),headers={Origin:base,'X-CSRF-Token':session.csrf_token};
  const playlists=[];
  for(const title of ['Independent playlist A','Independent playlist B']){
   const result=await context.request.post(base+'/api/playlists',{headers,data:{title,description:title+' description'}});
   assert.equal(result.status(),201);playlists.push(await result.json());
  }
  const page=await context.newPage(),errors=[],findings=[];
  let intentional503='';
  page.on('pageerror',e=>errors.push(e.message));
  page.on('console',m=>{if(m.type()==='error'&&!(intentional503&&m.location().url===base+intentional503&&/503/.test(m.text())))errors.push(m.text())});
  const title=page.getByLabel('Название',{exact:true}),description=page.getByLabel('Описание');
  const cancel=page.getByRole('button',{name:'Отменить изменения',exact:true});
  async function open(kind,id=playlists[0].id){
   await page.goto(base+(kind==='channel'?'/channels/'+name:'/studio/playlists/'+id));
   if(kind==='channel')await page.getByText('Редактировать канал',{exact:true}).click();
   await title.waitFor();
  }
  for(const width of [390,1440]){
   await page.setViewportSize({width,height:1000});
   for(const kind of ['channel','playlist']){
    const patch=kind==='channel'?'/api/me/channel':'/api/playlists/'+playlists[0].id;
    const get=kind==='channel'?'/api/channels/'+name:'/api/me/playlists/'+playlists[0].id;
    const save=page.getByRole('button',{name:kind==='channel'?'Сохранить канал':'Сохранить плейлист',exact:true});
    await open(kind);
    const original=await title.elementHandle();
    await title.fill('Focus draft '+kind);await description.fill('Focus draft description');
    intentional503=get;
    await page.route('**'+get,route=>route.fulfill({status:503,json:{message:'Independent refetch failure'}}));
    const failed=page.waitForResponse(r=>r.url()===base+get&&r.status()===503);
    await page.evaluate(()=>window.dispatchEvent(new Event('focus')));await (await failed).finished();
    await page.getByRole('alert').filter({hasText:'Independent refetch failure'}).waitFor();
    assert(await original.evaluate(node=>node.isConnected));
    assert.equal(await title.inputValue(),'Focus draft '+kind);
    assert.equal(await description.inputValue(),'Focus draft description');
    await page.unroute('**'+get);intentional503='';
    let refreshed=page.waitForResponse(r=>r.url()===base+get&&r.status()===200);
    await page.evaluate(()=>window.dispatchEvent(new Event('focus')));await(await refreshed).finished();
    await cancel.click();
    console.log('PASS '+kind+' '+width+' temporary GET failure retains draft and same form');

    // All PATCH/GET data remain real; only delay the network while the fields stay editable.
    await title.fill('Submitted A '+kind+' '+width);await description.fill('Submitted description A');
    let release;
    const held=new Promise(resolve=>release=resolve);
    let patchSeen;
    const seen=new Promise(resolve=>patchSeen=resolve);
    await page.route('**'+patch,async route=>{
     if(route.request().method()!=='PATCH')return route.continue();
     patchSeen();await held;const actual=await route.fetch();await route.fulfill({response:actual});
    });
    await save.click();await seen;
    assert(await title.isEditable());assert(await description.isEditable());
    const latest='Unsaved B typed during PATCH '+kind+' '+width;
    await title.fill(latest);await description.fill('Unsaved description B');
    refreshed=page.waitForResponse(r=>r.url()===base+get&&r.status()===200);
    release();await(await refreshed).finished();
    await page.waitForFunction(()=>!document.querySelector('.metadata-form button').disabled);
    await page.unroute('**'+patch);
    const actual=await title.inputValue();
    if(actual!==latest)findings.push({scenario:'edit-during-patch',kind,width,expected:latest,actual,description:await description.inputValue()});
    console.log('PATCH_PENDING_RESULT',JSON.stringify({kind,width,latest,actual}));

    // Successful save followed by a failing resource refetch.
    const savedBefore=await title.inputValue();
    const submitted='Successful PATCH with GET failure '+kind+' '+width;
    await title.fill(submitted);await description.fill('Successful PATCH description');
    intentional503=get;
    await page.route('**'+get,route=>route.fulfill({status:503,json:{message:'Independent post-save refetch failure'}}));
    const failedSaveRefresh=page.waitForResponse(r=>r.url()===base+get&&r.status()===503);
    await save.click();await(await failedSaveRefresh).finished();
    await page.getByRole('alert').filter({hasText:'Independent post-save refetch failure'}).waitFor();
    await page.waitForFunction(()=>!document.querySelector('.metadata-form button').disabled);
    const displayed=await title.inputValue(),server=await(await context.request.get(base+get)).json();
    assert.equal(server.title,submitted);
    if(displayed!==submitted)findings.push({scenario:'post-save-refetch-error',kind,width,expected:submitted,actual:displayed,savedBefore});
    console.log('SAVE_REFRESH_FAILURE_RESULT',JSON.stringify({kind,width,server:server.title,displayed}));
    assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
    await page.screenshot({path:`/artifacts/independent-${kind}-save-refetch-${width}.png`,fullPage:true});
    await page.unroute('**'+get);intentional503='';
    await open(kind);assert.equal(await title.inputValue(),submitted);
    assert.equal(await description.inputValue(),'Successful PATCH description');
    console.log('PASS '+kind+' '+width+' reopening shows saved server values, layout fits');
   }
  }
  await open('playlist');await title.fill('Draft belonging only to A');
  await page.getByRole('link',{name:'Открыть плейлист',exact:true}).click();
  await page.getByRole('link',{name:'Редактировать плейлист',exact:true}).click();
  assert.notEqual(await title.inputValue(),'Draft belonging only to A');
  await page.getByRole('link',{name:'Плейлисты',exact:true}).click();
  await page.getByRole('link',{name:'Independent playlist B',exact:true}).click();
  assert.equal(await title.inputValue(),'Independent playlist B');
  assert.equal(await description.inputValue(),'Independent playlist B description');
  console.log('PASS reopen and switching A/B do not transfer drafts');
  assert.deepEqual(errors,[]);
  writeFileSync('/artifacts/editor-findings.json',JSON.stringify(findings,null,2));
  console.log('CONFIRMED_FINDINGS',findings.length);
 }finally{await browser.close()}
})().catch(e=>{console.error(e.message);process.exitCode=1});

