const base='http://localhost:8080';
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 try{
  const errors=[];
  async function account(prefix){
   const context=await browser.newContext(),name=prefix+randomUUID().replaceAll('-','').slice(0,12);
   let response;
   for(let n=0;n<5;n++){
    response=await context.request.post(base+'/api/auth/register',{headers:{Origin:base},data:{username:name,email:name+'@example.com',password:randomUUID()}});
    if(response.status()!==429)break;await new Promise(resolve=>setTimeout(resolve,21000));
   }
   assert.equal(response.status(),201);
   const session=await response.json(),page=await context.newPage();
   page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
   return {context,page,name,headers:{Origin:base,'X-CSRF-Token':session.csrf_token}};
  }
  const owner=await account('chan7_'),viewer=await account('sub7_');
  assert.equal((await owner.context.request.patch(base+'/api/me/channel',{headers:owner.headers,data:{title:'Independent channel regression',description:'Real API fixture'}})).status(),200);
  const videos=[];
  for(const title of ['Awaiting clip A','Awaiting clip B']){
   const response=await owner.context.request.post(base+'/api/videos',{headers:owner.headers,data:{title,visibility:'private'}});
   assert.equal(response.status(),201);videos.push((await response.json()).id);
  }
  const p=owner.page,v=viewer.page;
  await p.goto(base+'/studio/playlists');await p.getByLabel('Название',{exact:true}).fill('Independent items regression');
  await p.getByRole('button',{name:'Создать плейлист',exact:true}).click();
  await p.getByRole('heading',{name:'Редактировать плейлист',exact:true}).waitFor();
  const playlist=p.url().split('/').pop();
  await p.getByLabel('Название',{exact:true}).fill('Unsaved metadata while changing items');
  const form=await p.getByLabel('Название',{exact:true}).elementHandle();
  for(let i=0;i<videos.length;i++){
   await p.getByLabel('Своё видео').selectOption(videos[i]);
   await p.getByRole('button',{name:'Добавить видео',exact:true}).click();
   await p.getByRole('button',{name:'Удалить из плейлиста: Awaiting clip '+(i?'B':'A'),exact:true}).waitFor();
   assert.equal(await p.getByLabel('Название',{exact:true}).inputValue(),'Unsaved metadata while changing items');
   assert(await form.evaluate(node=>node.isConnected));
  }
  await p.getByRole('button',{name:'Ниже: Awaiting clip A',exact:true}).click();
  await p.waitForFunction(()=>document.querySelector('.playlist-editor li span')?.textContent.startsWith('Awaiting clip B'));
  assert.deepEqual((await(await owner.context.request.get(base+'/api/me/playlists/'+playlist)).json()).items.map(item=>item.id),[videos[1],videos[0]]);
  assert.equal(await p.getByLabel('Название',{exact:true}).inputValue(),'Unsaved metadata while changing items');
  await p.getByRole('button',{name:'Отменить изменения',exact:true}).click();
  assert.equal(await p.getByLabel('Название',{exact:true}).inputValue(),'Independent items regression');
  await v.goto(base+'/channels/'+owner.name);
  await v.getByRole('button',{name:'Подписаться',exact:true}).click();
  await v.getByRole('button',{name:'Отписаться',exact:true}).waitFor();
  assert.equal(await v.getByTestId('subscribers-count').innerText(),'1');
  await v.reload();await v.getByRole('button',{name:'Отписаться',exact:true}).waitFor();
  assert((await(await viewer.context.request.get(base+'/api/me/subscriptions')).json()).items.some(item=>item.username===owner.name));
  const normalized='  '+viewer.name.toUpperCase()+'  ';
  assert.equal((await owner.context.request.put(`${base}/api/videos/${videos[0]}/access/${encodeURIComponent(normalized)}`,{headers:owner.headers})).status(),204);
  assert.equal((await owner.context.request.delete(`${base}/api/videos/${videos[0]}/access/${encodeURIComponent(normalized)}`,{headers:owner.headers})).status(),204);
  assert.deepEqual((await(await viewer.context.request.get(base+'/api/playlists/'+playlist)).json()).items,[]);
  for(const width of [390,1440]){
   for(const [page,label] of [[p,'playlist-items'],[v,'channel-subscription']]){
    await page.setViewportSize({width,height:1000});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
    await page.screenshot({path:`/artifacts/independent-${label}-${width}.png`,fullPage:true});
   }
  }
  await v.getByRole('button',{name:'Отписаться',exact:true}).click();await v.getByRole('button',{name:'Подписаться',exact:true}).waitFor();
  assert.deepEqual(errors,[]);
  console.log('PASS real API channel subscription/reload/unsubscribe, playlist create/add/reorder/cancel with draft retention, normalized grants/revoke, 390/1440 and clean console/pageerror; no uploads or FFmpeg');
 }finally{await browser.close()}
})().catch(e=>{console.error(e.message);process.exitCode=1});

